// =============================================================
//  BUILD REMINDER QUEUE
//  Required Node Setting: "Run Once for All Items"
// =============================================================

// ---------- 0. Configuration ---------------------------------
const CLINIC_NAME  = 'Your Clinic Agent';
const CLINIC_PHONE = '+92 42 111 222 333';
const CLINIC_TZ    = 'Asia/Karachi';
const LEAD_DAYS    = 1;
const TEST_MODE    = false; // Set to TRUE for testing (bypasses date matching)

// ---------- 1. Target Date Calculation ----------------------
let targetDate = '';
let runDate = '';

try {
  const now = DateTime.now().setZone(CLINIC_TZ);
  targetDate = now.plus({ days: LEAD_DAYS }).toFormat('yyyy-MM-dd');
  runDate    = now.toFormat('yyyy-MM-dd');
} catch (e) {
  const d = new Date();
  d.setDate(d.getDate() + LEAD_DAYS);
  targetDate = d.toISOString().split('T')[0];
  runDate    = new Date().toISOString().split('T')[0];
}

// ---------- 2. Helper Functions -----------------------------
const clean  = (v) => String(v ?? '').trim();
const isTrue = (v) => {
  const s = clean(v).toUpperCase();
  return s === 'TRUE' || s === '1' || v === true;
};
const E164  = /^\+[1-9]\d{7,14}$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const esc   = (v) => clean(v)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// ---------- 2b. WEBSITE INTEGRATION (ADDITIVE) ----------------
// This block, and every other change marked ADDITIVE in this file, was
// added so the same processing pipeline can also be triggered on-demand
// from the "Appointment Agent" web dashboard's "Webhook Trigger" node,
// instead of only the daily 9am "Schedule Trigger". It is wrapped in
// try/catch so a Schedule-Trigger run (where "Webhook Trigger" never
// executed) falls through unchanged and behaves exactly as the original
// workflow always did.
//
// Website request body shapes:
//   { "mode": "run" }                                  -> normal tomorrow batch
//   { "mode": "single",  "appointment_id": "A-1001" }   -> force-send one appointment
//   { "mode": "preview", "appointment_id": "A-1001" }   -> render only, never sends
let mode = 'run';
let targetAppointmentId = null;
let triggeredByWebhook = false;
try {
  const wh = $('Webhook Trigger').first();
  if (wh) {
    triggeredByWebhook = true;
    const body = (wh.json && wh.json.body) || {};
    if (body.mode === 'single' || body.mode === 'preview') {
      mode = body.mode;
      targetAppointmentId = clean(body.appointment_id) || null;
    }
  }
} catch (e) {
  // "Webhook Trigger" did not run this execution -> this is a Schedule-Trigger run.
}
const isTargeted = (mode === 'single' || mode === 'preview') && !!targetAppointmentId;

// ---------- 3. Process Items ---------------------------------
const queue = [];
const items = $input.all();
let matchedTargeted = false;

for (let i = 0; i < items.length; i++) {
  const r = items[i].json;

  if (isTargeted) {
    // ADDITIVE: website-triggered single send/preview -> match one
    // appointment_id regardless of its date, instead of the tomorrow filter.
    if (clean(r.appointment_id) !== targetAppointmentId) continue;
    matchedTargeted = true;
  } else {
    // 3a. Date filter (disabled when TEST_MODE = true)
    if (!TEST_MODE && clean(r.appointment_date) !== targetDate) {
      continue;
    }
  }

  const notScheduled = clean(r.status).toLowerCase() !== 'scheduled';
  const alreadySent  = clean(r.reminder_sent).toUpperCase() === 'YES';

  if (!isTargeted) {
    // 3b. Status filter
    if (notScheduled) continue;
    // 3c. Idempotency guard
    if (alreadySent) continue;
  }

  // 3d. Consent & Contact validation
  const phoneOk = E164.test(clean(r.phone_e164)) && isTrue(r.consent_sms);
  const emailOk = EMAIL.test(clean(r.email)) && isTrue(r.consent_email);

  let channel = null;
  let skip_reason = null;
  const preferred = clean(r.preferred_channel).toLowerCase();

  if (isTargeted && notScheduled) {
    // ADDITIVE: a forced send/preview on a non-Scheduled appointment is
    // reported back as a skip, never silently sent or previewed.
    skip_reason = 'not_scheduled';
  } else if (isTargeted && alreadySent) {
    // ADDITIVE: never bypass the idempotency guard just because an admin
    // clicked "Send" - report it back instead.
    skip_reason = 'already_reminded';
  } else if (preferred === 'sms' && phoneOk) {
    channel = 'sms';
  } else if (preferred === 'email' && emailOk) {
    channel = 'email';
  } else if (phoneOk) {
    channel = 'sms';
  } else if (emailOk) {
    channel = 'email';
  } else {
    skip_reason = (!isTrue(r.consent_sms) && !isTrue(r.consent_email))
      ? 'no_consent_on_file'
      : 'invalid_contact_details';
  }

  // 3e. Formatted Date & Time Parsing
  let readable_date = clean(r.appointment_date);
  let readable_time = clean(r.appointment_time);

  try {
    const when = DateTime.fromFormat(
      clean(r.appointment_date) + ' ' + clean(r.appointment_time),
      'yyyy-MM-dd HH:mm',
      { zone: CLINIC_TZ }
    );
    if (when.isValid) {
      readable_date = when.toFormat('cccc d LLLL');
      readable_time = when.toFormat('h:mm a');
    }
  } catch (e) {
    // Keep raw values if Luxon parsing fails
  }

  const first_name = clean(r.patient_first_name) || 'there';
  const clinician  = clean(r.clinician);
  const location   = clean(r.location);
  const apptId     = clean(r.appointment_id);

  // 3f. Pre-render SMS
  const sms_text =
    `${CLINIC_NAME}: Hi ${first_name}, reminder of your appointment on ` +
    `${readable_date} at ${readable_time} with ${clinician} ` +
    `(${location}). Ref ${apptId}. Reply C to cancel or call ${CLINIC_PHONE}.`;

  // 3g. Pre-render HTML Email
  const email_subject = `Appointment reminder - ${readable_date} at ${readable_time}`;
  const email_html =
    '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;color:#1f2933;line-height:1.6;">' +
      '<h2 style="margin:0 0 4px;color:#0b6b5b;">Appointment Reminder</h2>' +
      '<p style="margin:0 0 20px;color:#6b7280;font-size:13px;">' + esc(CLINIC_NAME) + '</p>' +
      '<p>Hi ' + esc(first_name) + ',</p>' +
      '<p>This is a reminder of your upcoming appointment.</p>' +
      '<table style="width:100%;border-collapse:collapse;font-size:14px;margin:18px 0;">' +
        '<tr><td style="padding:8px;border:1px solid #dde3ec;width:34%;background:#f6faf9;font-weight:bold;">Date</td>' +
        '<td style="padding:8px;border:1px solid #dde3ec;">' + esc(readable_date) + '</td></tr>' +
        '<tr><td style="padding:8px;border:1px solid #dde3ec;background:#f6faf9;font-weight:bold;">Time</td>' +
        '<td style="padding:8px;border:1px solid #dde3ec;">' + esc(readable_time) + '</td></tr>' +
        '<tr><td style="padding:8px;border:1px solid #dde3ec;background:#f6faf9;font-weight:bold;">Clinician</td>' +
        '<td style="padding:8px;border:1px solid #dde3ec;">' + esc(clinician) + '</td></tr>' +
        '<tr><td style="padding:8px;border:1px solid #dde3ec;background:#f6faf9;font-weight:bold;">Location</td>' +
        '<td style="padding:8px;border:1px solid #dde3ec;">' + esc(location) + '</td></tr>' +
        '<tr><td style="padding:8px;border:1px solid #dde3ec;background:#f6faf9;font-weight:bold;">Reference</td>' +
        '<td style="padding:8px;border:1px solid #dde3ec;">' + esc(apptId) + '</td></tr>' +
      '</table>' +
      '<p>Please arrive 10 minutes early. To cancel or reschedule, call <strong>' + esc(CLINIC_PHONE) + '</strong> at least 24 hours beforehand so we can offer the slot to another patient.</p>' +
      '<p style="margin-top:22px;">Kind regards,<br><strong>' + esc(CLINIC_NAME) + '</strong></p>' +
      '<hr style="border:none;border-top:1px solid #e3e8ef;margin:24px 0 10px;">' +
      '<p style="font-size:11px;color:#9aa5b1;margin:0;">Automated reminder. Please do not reply with medical information; this mailbox is not monitored by clinical staff.</p>' +
    '</div>';

  queue.push({
    json: {
      row_number:        r.row_number,
      appointment_id:    apptId,
      first_name,
      phone_e164:        clean(r.phone_e164),
      email:             clean(r.email),
      clinician,
      location,
      appointment_date: clean(r.appointment_date),
      readable_date,
      readable_time,
      channel,
      has_valid_contact: channel !== null,
      skip_reason,
      sms_text,
      email_subject,
      email_html,
      target_date:      targetDate,
      run_date:         runDate,
      mode // ADDITIVE: read by "Is Preview?" / "Log Run Summary" downstream
    }
  });

  if (isTargeted) break; // single/preview mode only ever needs one item
}

// ADDITIVE: if a website-triggered single send/preview named an
// appointment_id that matched nothing eligible above, guarantee one output
// item anyway so the webhook caller gets a real response instead of hanging.
if (isTargeted && !matchedTargeted) {
  queue.push({
    json: {
      row_number: null,
      appointment_id: targetAppointmentId,
      first_name: '',
      phone_e164: '',
      email: '',
      clinician: '',
      location: '',
      appointment_date: '',
      readable_date: '',
      readable_time: '',
      channel: null,
      has_valid_contact: false,
      skip_reason: 'not_found',
      sms_text: '',
      email_subject: '',
      email_html: '',
      target_date: targetDate,
      run_date: runDate,
      mode
    }
  });
}

// ADDITIVE: if this was a website-triggered batch run ("Run Reminder
// Agent") and nothing was due, the queue is legitimately empty - but an
// empty array here means NO downstream node fires at all (n8n does not run
// nodes on 0 input items), so the webhook caller would get no response.
// This marker item is caught by "Is Empty Webhook Run?" immediately after
// this node and routed straight to a zero-value response, WITHOUT flowing
// through "Has Valid Contact?" / "Log Skipped Records" / "Mark Reminder
// Sent", so it can never create a bogus Exceptions row or send anything.
// A Schedule-Trigger run with nothing due is untouched: queue stays
// genuinely empty and the workflow ends quietly, exactly as before.
if (!isTargeted && triggeredByWebhook && queue.length === 0) {
  queue.push({
    json: { __empty_run: true, run_date: runDate, target_date: targetDate, mode }
  });
}

// An empty array is still a valid, healthy result for a Schedule-Trigger
// run: it simply means no appointments are scheduled for the target date.
return queue;

// Items arriving here are the rows we successfully updated.
const sentCount = $input.all().length;
// Reach back to the queue for the full picture, including skips.
const queue   = $('Build Reminder Queue').all().map(i => i.json);
const total   = queue.length;
const skipped = queue.filter(q => !q.has_valid_contact);
const bySms   = queue.filter(q => q.channel === 'sms').length;
const byEmail = queue.filter(q => q.channel === 'email').length;
// Group the skip reasons so the front desk knows what to fix.
const reasons = {};
for (const s of skipped) {
  reasons[s.skip_reason] = (reasons[s.skip_reason] || 0) + 1;
}
const reasonText = Object.entries(reasons)
  .map(([k, v]) => k.replace(/_/g, ' ') + ': ' + v)
  .join(', ') || 'none';
const runDate    = queue[0]?.run_date    ?? DateTime.now().toFormat('yyyy-MM-dd');
const targetDate = queue[0]?.target_date ?? 'n/a';
const summary =
  '*Appointment Reminder Run - ' + runDate + '*\n' +
  'Appointments on ' + targetDate + ': *' + total + '*\n' +
  'Reminders sent: *' + sentCount + '*  (SMS ' + bySms +
  ', Email ' + byEmail + ')\n' +
  'Skipped: *' + skipped.length + '*  (' + reasonText + ')';
return [{
  json: { run_date: runDate, target_date: targetDate, total,
          sent: sentCount, skipped: skipped.length,
          by_sms: bySms, by_email: byEmail, summary }
}];

// ADDITIVE: a website-triggered batch run ("Run Reminder Agent") found
// nothing due tomorrow. Reports a real zero-value summary instead of
// leaving the request hanging - see the note in "Build Reminder Queue".
return [{
  json: {
    success: true,
    data: {
      run_date: $json.run_date,
      target_date: $json.target_date,
      total: 0,
      sent: 0,
      skipped: 0,
      by_sms: 0,
      by_email: 0
    }
  }
}];

// ADDITIVE: shapes a single reminder's rendered content for the website's
// "Send Reminder" preview dialog. Never sends anything - this branch is
// reached only when "Is Preview?" saw mode === 'preview', which happens
// BEFORE "Has Valid Contact?" / "Route by Channel" / the send nodes.
return [{
  json: {
    success: true,
    data: {
      appointment_id: $json.appointment_id,
      channel: $json.channel,
      has_valid_contact: $json.has_valid_contact,
      skip_reason: $json.skip_reason,
      sms_text: $json.sms_text,
      email_subject: $json.email_subject,
      email_html: $json.email_html
    }
  }
}];

// ADDITIVE: wraps Summarise Run's output in the website's standard
// {success, data} envelope for the "Run Reminder Agent" / "Send Reminder"
// API responses. Summarise Run's own output (and its existing Slack wire)
// is untouched - this is a read-only parallel branch.
return [{
  json: {
    success: true,
    data: {
      run_date: $json.run_date,
      target_date: $json.target_date,
      total: $json.total,
      sent: $json.sent,
      skipped: $json.skipped,
      by_sms: $json.by_sms,
      by_email: $json.by_email
    }
  }
}];
